import { Component, Injector, OnInit } from '@angular/core';
import { Observable } from 'rxjs';
import { CardPrincipal } from 'src/app/models/card-principal.model';
import { PexelsPhoto } from 'src/app/models/pexels/pexels-photo.model';
import { CardService } from 'src/app/services/card/card.service';
import { ImagesService } from 'src/app/services/external/images/images.service';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent implements OnInit{
  
  public cardPrincipal: CardPrincipal[] = [];
  private happyImage: PexelsPhoto = new PexelsPhoto;

  constructor(private cardService: CardService,
    private imageteste: ImagesService) {
    }

  ngOnInit() {
    this.loadCards();
    console.log('cards ', this.cardPrincipal)
    
    this.imageteste.getHappyImagesPexels().subscribe( {
      next: (result: PexelsPhoto[]) => {
        console.log('result ', result)
        this.happyImage = result;
      },
      error: err => {
        console.log(err)
      }
    })
    console.log('result ', this.happyImage)

  }

  // loadCards() {
  //   this.cardService.getCards()
  //   .subscribe(
  //     {
  //       next: (response: CardPrincipal) => {
  //         this.cardPrincipal.push(response);
  //       },
  //       error: (err) => {
  //         console.log(err)
  //       }
  //     }
  //   )
  // }

  // loadCards() {
  //   this.cardService.getCards()
  //   .subscribe(
  //     {
  //       next: (response: CardPrincipal[]) => {
  //         this.cardPrincipal = response;
  //       },
  //       error: (err) => {
  //         console.log(err)
  //       }
  //     }
  //   )
  // }

  loadCards() {
    this.cardService.getCards()
    .subscribe(
      {
        next: (response: CardPrincipal) => {
          if (Array.isArray(response)) {
            this.cardPrincipal.push(...response);
          }else {
            this.cardPrincipal.push(response); // todo refazer
          }
        },
        error: (err) => {
          console.log(err)
        }
      }
    )
  }

  addNewCard() {
    console.log("funcionando")
  }

  getHappyImage() {
    // console.log('getHappyImage ', this.happyImage[0].src.medium)
    if (this.happyImage.length > 0) {
      console.log('getHappyImage ', this.happyImage[0].src.medium)
      return this.happyImage[0].src.medium;
    } else {
      return ''; // ou alguma outra lógica de tratamento caso happyImage esteja vazio
    }
    // return this.happyImage[0].src.medium;
  }

}
